  const byId=new Map(topics.map(x=>[x.id,x]));
  const aliases=new Map();
  topics.forEach(x=>[x.displayTitle,...x.aliases].forEach(alias=>{const key=aliasKey(x.exam,x.subjectId,alias),matches=aliases.get(key)||[];if(!matches.includes(x))matches.push(x);aliases.set(key,matches)}));
