  function all({exam='',track='',subjectId='',active}={}){const e=String(exam||'').toUpperCase(),t=String(track||'').toUpperCase();return topics.filter(x=>(!e||x.exam===e)&&(!t||x.tracks.length===0||x.tracks.includes(t))&&(!subjectId||x.subjectId===subjectId)&&(active===undefined||x.active===active)).map(clone)}
  function get(id){return clone(byId.get(String(id||'').trim())||null)}
  function find({exam,subject,subjectId,topic}={}){const e=String(exam||'').toUpperCase(),sid=String(subjectId||'').trim(),topicKey=norm(topic);if(!e||!topicKey)return null;const resolvedSubject=sid||subjectRegistry.find(x=>x.exam===e&&norm(x.subject)===norm(subject))?.subjectId;if(!resolvedSubject)return null;const matches=aliases.get(aliasKey(e,resolvedSubject,topicKey))||[];return matches.length===1?clone(matches[0]):null}
